// Monta um envio por destinatário. modo 'teste' = só o Daniel; 'todos' = clientes ativos (lista do dyno_assessor_destinos em 08/10).
const NL = String.fromCharCode(10);
const body = ($('Disparo').first().json.body) || {};
const modo = body.modo === 'todos' ? 'todos' : 'teste';
const b64 = $input.first().json.base64;
if (!b64 || b64.length < 100000) throw new Error('Vídeo não baixado');
const CLIENTES = {"Luiz":"5511998254930","Jorge":"5511993684344","Lucas":"554688128343","Paulo":"5511984715429","Felipe":"5511964542058","Rafael":"5522974050629","Leandro":"5511996286968","Marcelo":"5511940055829","Matheus":"554184488908","Naianne":"5511966120784","Tavarez":"5511975813035","Anderson":"5511995176972","Roselena":"5511975821390","Marcos César":"5511951853133","Márcia Ferraz":"5511995924148"};
const lista = modo === 'todos' ? Object.entries(CLIENTES) : [['Daniel', '5511930851325']];
const legenda = nome => 'Oi, ' + nome.split(' ')[0] + '! 📦 *Novidade no Dyno: rastreio de encomendas*' + NL + NL +
  'Recebeu um código dos Correios? É só me mandar aqui, por texto ou print do SMS/e-mail. Eu acompanho e te aviso a cada mudança: postado, em trânsito, saiu para entrega e entregue.' + NL + NL +
  'E quando bater a curiosidade, é só perguntar: "cadê minha encomenda?" 😉';
return lista.map(([nome, numero]) => ({ json: { nome, numero, modo, legenda: legenda(nome), media: b64 } }));
